import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        String layout = st.nextToken(), word = st.nextToken();
        int[] pos = new int[26];
        for (int i = 0; i < 26; i++) pos[layout.charAt(i) - 'a'] = i;
        long answer = 0;
        int current = 0;
        for (int i = 0; i < word.length(); i++) {
            int p = pos[word.charAt(i) - 'a'];
            answer += Math.abs(p - current);
            current = p;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	r := bufio.NewReaderSize(os.Stdin, 1<<20)
	var layout, word string
	fmt.Fscan(r, &layout, &word)
	var pos [26]int
	for i := 0; i < 26; i++ {
		pos[layout[i]-'a'] = i
	}
	var answer int64
	current := 0
	for i := 0; i < len(word); i++ {
		p := pos[word[i]-'a']
		d := p - current
		if d < 0 {
			d = -d
		}
		answer += int64(d)
		current = p
	}
	fmt.Println(answer)
}
